from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Test valid event
    try:
        ServerSentEvent(event="test_event", id="test_id", data="test_data")
        print("Valid event passed")
    except ValidationError as e:
        print(f"Valid event failed: {e}")

    # Test event with newline
    try:
        ServerSentEvent(event="test\nevent", id="test_id", data="test_data")
        print("Event with newline should have failed")
    except ValidationError as e:
        print(f"Event with newline failed as expected: {e}")

    # Test id with newline
    try:
        ServerSentEvent(event="test_event", id="test\nid", data="test_data")
        print("Id with newline should have failed")
    except ValidationError as e:
        print(f"Id with newline failed as expected: {e}")

    # Test id with null character
    try:
        ServerSentEvent(event="test_event", id="test\0id", data="test_data")
        print("Id with null character should have failed")
    except ValidationError as e:
        print(f"Id with null character failed as expected: {e}")

    # Test data with newline (should be allowed)
    try:
        ServerSentEvent(event="test_event", id="test_id", data="test\ndata")
        print("Data with newline passed as expected")
    except ValidationError as e:
        print(f"Data with newline failed unexpectedly: {e}")

if __name__ == "__main__":
    test_sse_validation()

